CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','vendor','customer') NOT NULL DEFAULT 'customer',status ENUM('active','inactive','banned') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vendors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,store_name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,logo VARCHAR(255),banner VARCHAR(255),description TEXT,status ENUM('pending','approved','rejected') DEFAULT 'pending',commission_rate DECIMAL(5,2) DEFAULT 10.00,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,status ENUM('active','inactive') DEFAULT 'active',meta_title VARCHAR(190),meta_description TEXT);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT,sku VARCHAR(120),price DECIMAL(12,2) NOT NULL,sale_price DECIMAL(12,2) DEFAULT 0,stock INT DEFAULT 0,image VARCHAR(255),status ENUM('draft','active','inactive') DEFAULT 'draft',meta_title VARCHAR(190),meta_description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FULLTEXT(name,description),FOREIGN KEY(vendor_id) REFERENCES vendors(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE product_attributes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED,name VARCHAR(100),value VARCHAR(190),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED,sku VARCHAR(120),options_json JSON,price DECIMAL(12,2),stock INT,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED,path VARCHAR(255),sort_order INT DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) UNIQUE,type ENUM('fixed','percent'),value DECIMAL(12,2),starts_at DATETIME,ends_at DATETIME,status ENUM('active','inactive') DEFAULT 'active');
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,number VARCHAR(40) UNIQUE,status VARCHAR(40),payment_status VARCHAR(40),shipping_status VARCHAR(40),payment_method VARCHAR(40),total DECIMAL(12,2),commission_total DECIMAL(12,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED,product_id BIGINT UNSIGNED,vendor_id BIGINT UNSIGNED,quantity INT,price DECIMAL(12,2),total DECIMAL(12,2),commission DECIMAL(12,2),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED,amount DECIMAL(12,2),reason TEXT,status VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payouts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_id BIGINT UNSIGNED,amount DECIMAL(12,2),status ENUM('requested','approved','paid','rejected') DEFAULT 'requested',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,rating TINYINT,comment TEXT,status ENUM('pending','approved','rejected') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wishlists (user_id BIGINT UNSIGNED,product_id BIGINT UNSIGNED,PRIMARY KEY(user_id,product_id));
CREATE TABLE addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,label VARCHAR(80),line1 VARCHAR(190),city VARCHAR(100),state VARCHAR(100),postal_code VARCHAR(30),country VARCHAR(80));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,type VARCHAR(80),message TEXT,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,token_hash CHAR(64),expires_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (`key` VARCHAR(120) PRIMARY KEY,`value` TEXT);
CREATE TABLE activitylogs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(190),ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
